query:
SELECT p.plocation, COUNT(p.pnumber) AS project_count
FROM project p
GROUP BY p.plocation;

SELECT MAX(num_of_pieces) AS max_attendance
FROM 
    member_attendance;

SELECT MAX(level_of_membership) AS top_level
FROM 
    member;

SELECT branch_id, SUM(total_pounds) as total_sales
FROM purchase
GROUP BY branch_id;

SELECT c.city, c.regional_population
FROM city c
ORDER BY regional_population DESC;

SELECT c.city, c.gdp
FROM city c
ORDER BY gdp DESC;

SELECT e.lastname, e.firstname, e.title, e.reportsto, e.firstname, e.lastname
FROM employee e
JOIN employee m ON e.reportsto = m.employeeid;

SELECT a.aircraft, SUM(CAST(a.max_gross_weight AS INTEGER)) AS total_capacity
FROM aircraft a
GROUP BY a.aircraft;

SELECT a.aircraft, SUM(CAST(a.max_disk_loading AS INTEGER)) AS total_loading
FROM aircraft a
GROUP BY a.aircraft;

SELECT a.aircraft, SUM(CAST(a.total_disk_area AS INTEGER)) AS total_area
FROM aircraft a
GROUP BY a.aircraft;

SELECT f.origin, f.destination, AVG(f.price) AS avg_fare
FROM flight f
GROUP BY f.origin, f.destination;

SELECT AVG(s.age)
FROM singer s
WHERE s.is_male = TRUE;

SELECT genre_is, COUNT(*) AS count
FROM song
GROUP BY genre_is;

SELECT AVG(s.age)
FROM singer s
WHERE s.country = 'X';

SELECT AVG(rating)
FROM song
WHERE releasedate BETWEEN '2000-01-01' AND '2009-12-31';

SELECT AVG(s.age)
FROM singer s
WHERE s.is_male = FALSE;

SELECT languages, COUNT(*) AS count
FROM song
GROUP BY languages;

SELECT AVG(s.age)
FROM singer s
WHERE s.age > 35;

SELECT origin, COUNT(*) 
FROM train 
GROUP BY origin;

SELECT city, COUNT(*) 
FROM station 
GROUP BY city;

SELECT p.party, COUNT(*) as total_events
FROM party_events pe JOIN party p ON pe.party_id = p.party_id
GROUP BY p.party;

SELECT age_group, COUNT(*) as total_members
FROM (SELECT age/10*10 as age_group FROM member) AS subquery
GROUP BY age_group;

SELECT r.region_name, COUNT(*) as total_events
FROM member m JOIN region r ON m.address = r.region_name
GROUP BY r.region_name;

SELECT country, COUNT(*) AS count
FROM perpetrator
GROUP BY country;

SELECT height, COUNT(*) AS count
FROM people
GROUP BY height;

SELECT *
FROM people
WHERE birth_date LIKE '%______';

SELECT location, COUNT(*) AS count
FROM perpetrator
GROUP BY location;

SELECT name, COUNT(*) AS count
FROM people
GROUP BY name;

SELECT *
FROM people
WHERE height IS NULL;

SELECT SUM(total_points) 
FROM gymnast 
WHERE 1 = (SELECT COUNT(*) FROM gymnast WHERE gymnast_id = gymnast_id);
